const MOUNTAINS=[
  {name:'Thredbo',   lat:-36.5058, lon:148.3044, airport:'CBR', region:'Snowy Mountains, NSW'},
  {name:'Perisher',  lat:-36.4052, lon:148.4120, airport:'CBR', region:'Snowy Mountains, NSW'},
  {name:'Mt Buller', lat:-37.1472, lon:146.4439, airport:'MEL', region:'Victorian Alps, VIC'},
  {name:'Mt Hotham', lat:-36.9764, lon:147.1356, airport:'MHU', region:'Victorian Alps, VIC'}
];
// Open-Meteo returns one object per coordinate, in request order. n8n may hand it back
// as separate items, one item wrapping the array, or a raw JSON string.
function load(name){
  let items=$(name).all().map(i=>i.json);
  if(items.length===1){
    const it=items[0];
    if(typeof it==='string') items=JSON.parse(it);
    else if(typeof it.data==='string') items=JSON.parse(it.data);
    else if(Array.isArray(it.data)) items=it.data;
    else if(Array.isArray(it)) items=it;
    else items=[it];
  }
  return items;
}
const locs=load('Open-Meteo Snow');
const out=[];
locs.forEach((loc,idx)=>{
  const m=MOUNTAINS[idx];
  if(!m||!loc||!loc.daily) return;
  const d=loc.daily, h=loc.hourly||{};
  const baseByDay={};
  (h.time||[]).forEach((t,i)=>{
    const depth=(h.snow_depth||[])[i];
    if(depth==null) return;
    const day=t.slice(0,10);
    baseByDay[day]=Math.max(baseByDay[day]||0, depth*100); // metres -> cm
  });
  d.time.forEach((day,i)=>{
    const snowfallCm=Math.round((d.snowfall_sum[i]||0)*10)/10;
    out.push({json:{
      mountain:m.name, airport:m.airport, region:m.region,
      date:day,
      day:new Date(day+'T00:00:00Z').toUTCString().slice(0,3),
      snowfallCm,
      tempMax:d.temperature_2m_max[i],
      tempMin:d.temperature_2m_min[i],
      windKts:Math.round(d.wind_speed_10m_max[i]||0),
      baseCm:Math.round(baseByDay[day]||0)
    }});
  });
});
return out;

const MIN_SNOWFALL_CM=10, MAX_TEMP_C=2, MAX_WIND_KTS=40, MIN_ON_DAYS=3, FORCE_FIRE=false; // FORCE_FIRE=true to fire on camera anytime
const rows=$('Forecast').all().map(i=>i.json);
const byMtn={};
for(const r of rows){
  const m=byMtn[r.mountain]||(byMtn[r.mountain]={mountain:r.mountain,airport:r.airport,region:r.region,onDates:[],lines:[],total:0,peak:0,base:0});
  m.total+=r.snowfallCm;
  if(r.snowfallCm>m.peak) m.peak=r.snowfallCm;
  if(r.baseCm>m.base) m.base=r.baseCm;
  const dumping = r.snowfallCm>=MIN_SNOWFALL_CM && r.tempMax<=MAX_TEMP_C && r.windKts<=MAX_WIND_KTS;
  if(dumping){
    m.onDates.push(r.date);
    m.lines.push(`${r.day}: ${r.snowfallCm}cm fresh · ${Math.round(r.tempMin)}° to ${Math.round(r.tempMax)}° · ${r.windKts}kts`);
  }
}
const ranked=Object.values(byMtn).sort((a,b)=> (b.onDates.length-a.onDates.length) || (b.total-a.total));
const best=ranked[0];
const powderOn=FORCE_FIRE || best.onDates.length>=MIN_ON_DAYS;
const departDate=best.onDates[0]||rows[0].date;
const rt=new Date((best.onDates[best.onDates.length-1]||departDate)+'T00:00:00Z'); rt.setUTCDate(rt.getUTCDate()+1);
return [{json:{powderOn,
  mountain:best.mountain, airport:best.airport, region:best.region,
  departDate, returnDate:rt.toISOString().slice(0,10),
  snowLines:best.lines.join('\n'),
  peakSnowfallCm:best.peak, totalSnowfallCm:Math.round(best.total), baseDepthCm:best.base,
  onDays:best.onDates.length||3,
  runnersUp:ranked.slice(1).map(m=>`${m.mountain} ${Math.round(m.total)}cm`).join(' · '),
  forecastUrl:`https://www.snow-forecast.com/resorts/${best.mountain.replace(/[^a-zA-Z]+/g,'-')}/6day/top`}}];

