let fitem=$('Apify Flights').first().json; if(Array.isArray(fitem))fitem=fitem[0];
const flights=(fitem&&fitem.all_flights)||[];
const cf=flights.filter(x=>x.price).sort((a,b)=>a.price-b.price)[0]||{};
const direct=(cf.stops===0||cf.stops==='0')?', direct':'';
const flightLine=`from A$${cf.price} return (${cf.airlines||'?'}${direct})`;
let lodges=$('Apify Lodge').all().map(i=>i.json);
if(lodges.length===1&&Array.isArray(lodges[0]))lodges=lodges[0];
if(lodges.length===1&&lodges[0]&&Array.isArray(lodges[0].data))lodges=lodges[0].data;
function pn(it){const d=(((it.price||{}).breakDown||{}).basePrice||{}).description||'';const m=d.match(/x\s*\$?([\d,.]+)/);return m?Math.round(parseFloat(m[1].replace(/,/g,''))):null;}
const lp=lodges.map(v=>({pn:pn(v),url:(v.url||'').split('?')[0]})).filter(v=>v.pn).sort((a,b)=>a.pn-b.pn);
const cl=lp[0]||{};
return [{json:{flightLine,lodgePrice:cl.pn,lodgeUrl:cl.url||'https://www.airbnb.com'}}];

const s=$('Evaluate snow').first().json, p=$('Pick cheapest').first().json;
let short=$('Shorten lodge').first().json;
short=(typeof short==='string')?short:(short.data||short.body||'');
if(!/^https:\/\/da\.gd\//.test(short)) short=p.lodgeUrl; // fallback to clean full url if da.gd errored
const message=`🎿❄️ POWDER EVENT — ${s.mountain} is about to get BURIED

🌨️ Fresh: ${s.totalSnowfallCm}cm total, peak ${s.peakSnowfallCm}cm in a day
🏔️ Base: ${s.baseDepthCm}cm · ${s.region}
🌬️ Cold, and winds inside lift limits
📅 Dumping ${s.onDays} days straight:

${s.snowLines}

✈️ Flights SYD→${s.airport}: ${p.flightLine}
🛖 Lodge: A$${p.lodgePrice}/night → ${short}
🥈 Runners-up: ${s.runnersUp}

📊 Forecast: ${s.forecastUrl}

👇 Crew — you in?`;
return [{json:{message}}];

// In production this is driven by the Telegram poll_answer webhook (who tapped "I'm in").
// For the shareable/demo workflow we proceed with the crew who opted in.
return [{json:{optedIn:true, note:"prod: Telegram poll_answer webhook supplies the opted-in crew"}}];

// Build the flight-options email from the Apify flights scrape (top 4 cheapest).
let fitem=$('Apify Flights').first().json; if(Array.isArray(fitem))fitem=fitem[0];
const flights=((fitem&&fitem.all_flights)||[]).filter(x=>x.price).sort((a,b)=>a.price-b.price).slice(0,4);
const s=$('Evaluate snow').first().json;
const rows=flights.length
  ? flights.map((f,i)=>`${i+1}. A$${f.price} — ${f.airlines} (${(f.stops===0||f.stops==='0')?'direct':(f.stops||'?')+' stop'})`).join('\n')
  : "(no live flights in pinned data)";
const subject=`🎿 POWDER EVENT — ${s.mountain} flights to book (${s.departDate} → ${s.returnDate})`;
const message=`${s.mountain} is about to get buried. Flights SYD→${s.airport} for ${s.departDate} → ${s.returnDate}:\n\n${rows}\n\n`+
  `Book one and the workflow takes over — it's now watching your inbox for the airline confirmation, then it tracks the flight and books the snow transfer + après supplies.`;
return [{json:{subject,message,to:"YOUR_EMAIL@example.com"}}];

// In production: poll a flight-status API (AeroDataBox / AviationStack) for live ETA.
